css:
@font-face {
  font-family: "Google Sans Flex";
  font-style: normal;
  font-weight: 100 900;
  font-display: swap;
  src: url("data:font/woff2;base64,") format("woff2");
  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}

@font-face {
  font-family: "Google Sans Code";
  font-style: normal;
  font-weight: 300 800;
  font-display: swap;
  src: url("data:font/woff2;base64,") format("woff2");
  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}





.omd [data-omd-part="sidebar"] {
  background-color: var(--omd-sidebar);
  border-right-color: var(--omd-border);
  border-right-style: solid;
  border-right-width: 1px;
  color: var(--omd-text);
  font-family: var(--omd-font-ui);
}



.omd [data-omd-part="header"] {
  background-color: var(--omd-sidebar);
  border-bottom-color: var(--omd-border);
  border-bottom-style: solid;
  border-bottom-width: 1px;
  color: var(--omd-text);
  font-family: var(--omd-font-ui);
  font-weight: 500;
  letter-spacing: 0;
}



.omd [data-omd-part="conversation"] {
  background-color: var(--omd-surface);
  color: var(--omd-text);
  font-family: var(--omd-font-body);
}

.omd[data-appearance="dark"] [data-omd-part="conversation"] {
  background-color: var(--omd-bg);
}



.omd [data-omd-part="composer"] {
  background-color: var(--omd-surface-container-high);
  border-color: var(--omd-border);
  border-style: solid;
  border-width: 1px;
  border-radius: var(--omd-radius-composer);
  box-shadow: var(--omd-shadow);
}

.omd [data-omd-part="input"] {
  background-color: transparent;
  border-color: transparent;
  border-style: solid;
  border-width: 1px;
  border-radius: var(--omd-radius-control);
  color: var(--omd-text);
  font-family: var(--omd-font-ui);
  font-weight: 400;
}



.omd [data-omd-part="workbench"] {
  background-color: var(--omd-surface-container);
  border-left-color: var(--omd-border);
  border-left-style: solid;
  border-left-width: 1px;
  color: var(--omd-text);
}

.omd[data-appearance="dark"] [data-omd-part="workbench"] {
  background-color: var(--omd-surface);
}



.omd [data-omd-part="settings"] {
  background-color: var(--omd-surface);
  color: var(--omd-text);
  font-family: var(--omd-font-body);
}



.omd [data-omd-part="dialog"] {
  background-color: var(--omd-surface-container-high);
  border-radius: var(--omd-radius-dialog);
  box-shadow: var(--omd-shadow-dialog);
  color: var(--omd-text);
  font-family: var(--omd-font-ui);
}

.omd[data-appearance="dark"] [data-omd-part="dialog"] {
  border-color: var(--omd-border);
  border-style: solid;
  border-width: 1px;
}

.omd [data-omd-part="menu"] {
  background-color: var(--omd-surface-container-high);
  border-radius: var(--omd-radius-menu);
  box-shadow: var(--omd-shadow-menu);
  color: var(--omd-text);
  font-family: var(--omd-font-ui);
}



.omd [data-omd-part="code"] {
  font-family: var(--omd-font-mono);
  letter-spacing: 0;
}

.omd [data-omd-part="button"] {
  font-family: var(--omd-font-ui);
  font-weight: 500;
  letter-spacing: 0;
  outline-offset: 2px;
}


.omd [data-omd-part="button"]:focus-visible {
  outline-color: var(--omd-focus);
  outline-style: solid;
  outline-width: 3px;
}


.omd [data-omd-part="button"]:disabled {
  border-color: var(--omd-border);
  box-shadow: none;
}



.omd [data-omd-part="tool"] {
  background-color: transparent;
  font-family: var(--omd-font-mono);
  font-weight: 400;
  letter-spacing: 0;
}





.omd [data-omd-part="sidebar-row"] {
  border-color: transparent;
  border-radius: var(--omd-radius-pill);
  color: var(--omd-text);
  font-family: var(--omd-font-ui);
  font-weight: 500;
  letter-spacing: 0;
}

.omd [data-omd-part="sidebar-row"]:hover {
  background-color: var(--omd-hover);
}

.omd [data-omd-part="sidebar-row"][data-omd-state="selected"] {
  background-color: var(--omd-selected);
  color: var(--omd-accent);
}



.omd [data-omd-part="message-user"] {
  background-color: var(--omd-user-bg);
  border-color: transparent;
  border-radius: var(--omd-radius-panel);
  color: var(--omd-text);
  font-family: var(--omd-font-body);
}



.omd [data-omd-part="process-toggle"] {
  border-radius: var(--omd-radius-control);
  color: var(--omd-muted);
  font-family: var(--omd-font-ui);
  font-weight: 500;
  letter-spacing: 0;
}

.omd [data-omd-part="process-toggle"]:hover {
  background-color: var(--omd-hover);
  color: var(--omd-text);
}

.omd [data-omd-part="tool-group"] {
  background-color: transparent;
  border-color: var(--omd-border);
  border-style: solid;
  border-width: 0;
}

.omd [data-omd-part="tool-row"] {
  background-color: transparent;
  color: var(--omd-muted);
  font-family: var(--omd-font-mono);
  font-weight: 400;
  letter-spacing: 0;
}



.omd [data-omd-part="code-block"] {
  background-color: var(--omd-code-bg);
  border-radius: var(--omd-radius-control);
  color: var(--omd-text);
  font-family: var(--omd-font-mono);
  letter-spacing: 0;
}

.omd [data-omd-part="code-inline"] {
  background-color: var(--omd-code-bg);
  border-radius: var(--omd-radius-menu);
  color: var(--omd-text);
  font-family: var(--omd-font-mono);
  letter-spacing: 0;
}



.omd [data-omd-part="statusbar"] {
  color: var(--omd-muted);
  font-family: var(--omd-font-ui);
  font-variant-numeric: tabular-nums;
}



.omd [data-omd-part="settings-shell"] {
  background-color: var(--omd-surface);
  border-color: var(--omd-border);
  border-style: solid;
  border-width: 1px;
  border-radius: var(--omd-radius-dialog);
  box-shadow: var(--omd-shadow-dialog);
  color: var(--omd-text);
  font-family: var(--omd-font-ui);
}

.omd[data-appearance="dark"] [data-omd-part="settings-shell"] {
  background-color: var(--omd-surface);
}

.omd [data-omd-part="settings-nav"] {
  background-color: var(--omd-sidebar);
  border-color: var(--omd-border);
  border-style: solid;
  border-width: 0;
  color: var(--omd-text);
  font-family: var(--omd-font-ui);
}

.omd [data-omd-part="settings-nav-item"] {
  border-radius: var(--omd-radius-pill);
  color: var(--omd-muted);
  font-family: var(--omd-font-ui);
  font-weight: 500;
  letter-spacing: 0;
}

.omd [data-omd-part="settings-nav-item"]:hover {
  background-color: var(--omd-hover);
  color: var(--omd-text);
}

.omd [data-omd-part="settings-nav-item"][data-omd-state="selected"] {
  background-color: var(--omd-selected);
  color: var(--omd-accent);
}

.omd [data-omd-part="settings-content"] {
  background-color: transparent;
  color: var(--omd-text);
  font-family: var(--omd-font-body);
}

.omd [data-omd-part="settings-row"] {
  border-color: var(--omd-border);
  border-radius: var(--omd-radius-control);
  color: var(--omd-text);
  font-family: var(--omd-font-ui);
}



.omd [data-omd-part="settings-tabs"] {
  background-color: var(--omd-surface-container);
  border-radius: var(--omd-radius-control);
  color: var(--omd-muted);
  font-family: var(--omd-font-ui);
}

.omd [data-omd-part="tab"] {
  background-color: transparent;
  border-color: transparent;
  border-radius: var(--omd-radius-control);
  color: var(--omd-muted);
  font-family: var(--omd-font-ui);
  font-weight: 500;
  letter-spacing: 0;
}

.omd [data-omd-part="tab"]:hover {
  background-color: var(--omd-hover);
  color: var(--omd-text);
}

.omd [data-omd-part="tab"][data-omd-state="selected"] {
  background-color: var(--omd-surface-solid);
  color: var(--omd-accent);
}

.omd [data-omd-part="segments"] {
  background-color: var(--omd-surface-container);
  border-color: transparent;
  border-radius: var(--omd-radius-pill);
  color: var(--omd-muted);
  font-family: var(--omd-font-ui);
}

.omd [data-omd-part="segment"] {
  background-color: transparent;
  border-color: transparent;
  border-radius: var(--omd-radius-pill);
  color: var(--omd-muted);
  font-family: var(--omd-font-ui);
  font-weight: 500;
  letter-spacing: 0;
}

.omd [data-omd-part="segment"]:hover {
  background-color: var(--omd-hover);
  color: var(--omd-text);
}

.omd [data-omd-part="segment"][data-omd-state="selected"] {
  background-color: var(--omd-selected);
  color: var(--omd-accent);
}



.omd [data-omd-part="form-control"] {
  background-color: var(--omd-surface);
  border-color: var(--omd-border);
  border-style: solid;
  border-width: 1px;
  border-radius: var(--omd-radius-control);
  caret-color: var(--omd-accent);
  color: var(--omd-text);
  font-family: var(--omd-font-ui);
}

.omd [data-omd-part="field-input"] {
  background-color: var(--omd-surface);
  border-color: var(--omd-border);
  border-style: solid;
  border-width: 1px;
  border-radius: var(--omd-radius-control);
  caret-color: var(--omd-accent);
  color: var(--omd-text);
  font-family: var(--omd-font-ui);
}

.omd [data-omd-part="field-input"]:focus-within {
  border-color: var(--omd-focus);
  outline-color: var(--omd-focus);
  outline-style: solid;
  outline-width: 1px;
}

.omd [data-omd-part="select"] {
  background-color: var(--omd-surface);
  border-color: var(--omd-border);
  border-style: solid;
  border-width: 1px;
  border-radius: var(--omd-radius-control);
  color: var(--omd-text);
  font-family: var(--omd-font-ui);
}

.omd [data-omd-part="select"]:focus-within {
  border-color: var(--omd-focus);
}

.omd [data-omd-part="file-input"] {
  background-color: var(--omd-surface);
  border-color: var(--omd-border);
  border-style: solid;
  border-width: 1px;
  border-radius: var(--omd-radius-control);
  color: var(--omd-text);
  font-family: var(--omd-font-ui);
}

.omd [data-omd-part="checkbox"] {
  accent-color: var(--omd-switch-on);
  color: var(--omd-switch-on);
}

.omd [data-omd-part="switch"] {
  accent-color: var(--omd-switch-on);
  background-color: var(--omd-surface-container-high);
  border-color: var(--omd-border);
  border-style: solid;
  border-width: 1px;
  border-radius: var(--omd-radius-pill);
}

.omd [data-omd-part="switch"][data-omd-state="checked"] {
  background-color: var(--omd-switch-on);
  border-color: var(--omd-switch-on);
}

.omd [data-omd-part="savebar"] {
  background-color: transparent;
  border-top-color: var(--omd-border);
  border-top-style: solid;
  border-top-width: 1px;
  font-family: var(--omd-font-ui);
}



.omd [data-omd-part="button-primary"] {
  background-color: var(--omd-button-bg);
  border-color: var(--omd-button-bg);
  border-style: solid;
  border-width: 1px;
  border-radius: var(--omd-radius-pill);
  box-shadow: var(--omd-shadow);
  color: var(--omd-button-fg);
  font-family: var(--omd-font-ui);
  font-weight: 500;
  letter-spacing: 0;
}

.omd [data-omd-part="button-primary"]:hover {
  background-color: var(--omd-button-hover);
  border-color: var(--omd-button-hover);
}

.omd [data-omd-part="button-primary"][data-omd-state="disabled"] {
  background-color: var(--omd-surface-container);
  border-color: var(--omd-border);
  box-shadow: none;
  color: var(--omd-muted);
}

.omd [data-omd-part="button-quiet"] {
  background-color: transparent;
  border-color: transparent;
  border-style: solid;
  border-width: 1px;
  border-radius: var(--omd-radius-pill);
  color: var(--omd-muted);
  font-family: var(--omd-font-ui);
  font-weight: 500;
  letter-spacing: 0;
}

.omd [data-omd-part="button-quiet"]:hover {
  background-color: var(--omd-hover);
  color: var(--omd-text);
}

.omd [data-omd-part="icon-button"] {
  background-color: transparent;
  border-color: transparent;
  border-style: solid;
  border-width: 1px;
  border-radius: var(--omd-radius-pill);
  color: var(--omd-muted);
}

.omd [data-omd-part="icon-button"]:hover {
  background-color: var(--omd-hover);
  color: var(--omd-text);
}

.omd [data-omd-part="send"] {
  background-color: var(--omd-button-bg);
  border-color: var(--omd-button-bg);
  border-style: solid;
  border-width: 1px;
  border-radius: var(--omd-radius-pill);
  box-shadow: var(--omd-shadow);
  color: var(--omd-button-fg);
}

.omd [data-omd-part="send"]:hover {
  background-color: var(--omd-button-hover);
  border-color: var(--omd-button-hover);
}
